package books;

public interface BookFilterStrategy {
    boolean test(Book book);
}

package books;

public class YearAfterFilter implements BookFilterStrategy{

    private int year;

    public YearAfterFilter(int year) {
        this.year = year;
    }

    public boolean test(Book book) {
        return book.getYear() > year;
    }
}

package books;

public class AuthorFilter implements BookFilterStrategy {

    private String author;

    public AuthorFilter(String author) {
        this.author = author;
    }

    public boolean test(Book book) {
        return book.getAuthor().equals(author);
    }
}

package books;

import java.util.ArrayList;
import java.util.List;

public class Book {
    private String title;
    private String author;
    private int year;

    public Book(String title, String author, int year) {
        this.title = title;
        this.author = author;
        this.year = year;
    }

    public String getTitle() {
        return title;
    }

    public String getAuthor() {
        return author;
    }

    public int getYear() {
        return year;
    }

    @Override
    public String toString() {
        return title + " " + author + " " + year;
    }

    // static solution (value parametrization)
    public static List<Book> filterBooksAfterYear(List<Book> books, int year) {
        List<Book> result = new ArrayList<>();
        for (Book book : books) {
            if (book.getYear() > year) {
                result.add(book);
            }
        }
        return result;
    }
    // also static
    public static List<Book> filterBooksByAuthor(List<Book> books, String author) {
        List<Book> result = new ArrayList<>();
        for (Book book : books) {
            if (book.getAuthor().equals(author)) {
                result.add(book);
            }
        }
        return result;
    }

    // with behavioral parametrization
    public static List<Book> filterBooks(List<Book> books , BookFilterStrategy... strategies){
        if (books == null || books.isEmpty() || strategies == null || strategies.length == 0) {
            return books;
        }
        List<Book> result = new ArrayList<>();
        for (Book book : books) {
            boolean pass = true;
            for (BookFilterStrategy strategy : strategies) {
                if(!strategy.test(book)){
                    pass = false;
                    break;
                }
            }
            if (pass) result.add(book);
        }
        return result;
    }

    public static void main(String[] args) {
        List<Book> books = new ArrayList<>();
        books.add(new Book("books.Book 1", "Author 1", 1974));
        books.add(new Book("books.Book 2", "Author 2", 2022));
        books.add(new Book("books.Book 3", "Author 3", 1970));
        books.add(new Book("books.Book 4", "Author 1", 2002));
        books.add(new Book("books.Book 5", "Author 2", 2008));

        System.out.println(Book.filterBooksByAuthor(books, "Author 1"));
        System.out.println(Book.filterBooks(books, new YearAfterFilter(1998), new AuthorFilter("Author 1")));
    }

}

