     * This enables you to work on this homework without listening to the sounds.
     */
    private final static boolean PRINT_PLAYING_NOTES = true;

    public static void main(String[] args) {
        // C major chord with piano (instrument 1)
        MidiPlayer.registerNote(60, 100, 0, 1000, 1);
        MidiPlayer.registerNote(64, 100, 0, 1000, 1);
        MidiPlayer.registerNote(67, 100, 0, 1000, 1);

        // F major chord with strings (instrument 49) after 1 second
        MidiPlayer.registerNote(65, 100, 1000, 1000, 49);
        MidiPlayer.registerNote(69, 100, 1000, 1000, 49);
        MidiPlayer.registerNote(72, 100, 1000, 1000, 49);

        // Bass note with electric bass (instrument 35)
        MidiPlayer.registerNote(41, 300, 500, 1500, 35);
        MidiPlayer.registerNote(41, 300, 500, 1500, 35);

        MidiPlayer.playNow();

        MidiPlayer.shutdown();
    }

    private record NoteEvent(int note, int velocity, long startTimeMs, long durationMs, int instrument) {}

    private static final List<NoteEvent> events = new ArrayList<>();

    private static Synthesizer synthesizer;
    private static MidiChannel[] channels;

    static {
        try {
            synthesizer = MidiSystem.getSynthesizer();
            synthesizer.open();
            synthesizer.loadAllInstruments(synthesizer.getDefaultSoundbank());
            channels = synthesizer.getChannels();
        } catch (MidiUnavailableException e) {
            e.printStackTrace();
        }
    }

    /**
     * Register a note to be played later.
     *
     * @param note        MIDI note number (60 = middle C)
     * @param velocity    intensity (0–127)
     * @param startTimeMs when to start playing (in ms, relative to playNow())
     * @param durationMs  how long to hold the note (in ms)
     * @param instrument  MIDI instrument number (1–128)
     */
    public static void registerNote(int note, int velocity, long startTimeMs, long durationMs, int instrument) {
        // We save the instrument index (0-indexed) instead of the instrument number (1-indexed) internally, so we save instrument-1 instead of just the instruments
        events.add(new NoteEvent(note, velocity, startTimeMs, durationMs, instrument-1));
    }

    /**
     * Register a note to be played later.
     *
     * @param note        MIDI note number (60 = middle C)
     * @param velocity    intensity (0–127)
     * @param startTimeMs when to start playing (in ms, relative to playNow())
     * @param durationMs  how long to hold the note (in ms)
     */
    public static void registerNote(int note, int velocity, long startTimeMs, long durationMs) {
        registerNote(note, velocity, startTimeMs, durationMs, 1);
    }

    /**
     * Plays all registered notes in sorted order according to their start times.
     */
    public static void playNow() {
        if (events.isEmpty()) {
            System.out.println("No notes registered.");
            return;
        }

        // sort events by start time
        events.sort(Comparator.comparingLong(a -> a.startTimeMs));

        long maxStartTime = events.getLast().startTimeMs;
        int startTimeMaxTextWidth = String.valueOf(maxStartTime).length();
        String formatStringToPrintNotes = "%" + startTimeMaxTextWidth + "d: Playing note %d for duration %s (ms) on instrument %d\n";

        // we need to count how many notes need to shut down until the end
        CountDownLatch latch = new CountDownLatch(events.size());
        long start = System.currentTimeMillis();

        for (NoteEvent event : events) {
            long delay = event.startTimeMs - (System.currentTimeMillis() - start);
            if (delay > 0) {
                try {
                    Thread.sleep(delay);
                } catch (InterruptedException ignored) {}
            }

            // Choose a channel and set instrument
            MidiChannel channel = channels[event.instrument % channels.length];
            channel.programChange(event.instrument);

            // Start note
            channel.noteOn(event.note, event.velocity);

            if (PRINT_PLAYING_NOTES) {
                System.out.printf(formatStringToPrintNotes, event.startTimeMs, event.note, event.durationMs, event.instrument);
            }

            // Schedule note off
            new Thread(() -> {
                try {
                    Thread.sleep(event.durationMs);
                } catch (InterruptedException ignored) {}
                channel.noteOff(event.note);
                latch.countDown();
            }).start();
        }

        // Wait until all note-off calls are done, and then wait a bit more so that the last note can tamper off.
        try {
            latch.await();
            Thread.sleep(500);
        } catch (InterruptedException ignored) {}

        // Clear events after playback
        events.clear();
    }

    public static void shutdown() {
        if (synthesizer != null && synthesizer.isOpen()) {
            synthesizer.close();
        }
    }

    /**
     * This method is used to create the example files in the template
     * @param filename where to save the file to (relative to the project folder)
     */
    public static void saveToFile(String filename) {
        if (events.isEmpty()) {
            System.out.println("No notes registered.");
            return;
        }

        try {
            // Create a MIDI sequence with PPQ (pulses per quarter note) timing
            Sequence sequence = new Sequence(Sequence.PPQ, 480);
            Track track = sequence.createTrack();

            int tempo = 500000; // microseconds per quarter note (120 bpm)
            MetaMessage tempoMessage = new MetaMessage();
            tempoMessage.setMessage(0x51, new byte[] {
                    (byte)((tempo >> 16) & 0xFF),
                    (byte)((tempo >> 8) & 0xFF),
                    (byte)(tempo & 0xFF)
            }, 3);
            track.add(new MidiEvent(tempoMessage, 0));

            // Sort events by start time
            events.sort(Comparator.comparingLong(a -> a.startTimeMs));

            // Tempo: 120 BPM = 500000 microseconds per quarter note
            int ppq = 480;
            double bpm = 120.0;
            double msPerQuarter = 60000.0 / bpm; // 60000 ms per minute / BPM = 500 ms per quarter
            double ticksPerMs = ppq / msPerQuarter; // = 480 / 500 = 0.96

            for (NoteEvent event : events) {
                long tickStart = Math.round(event.startTimeMs * ticksPerMs);
                long tickEnd = Math.round((event.startTimeMs + event.durationMs) * ticksPerMs);

                int channel = event.instrument % 16; // valid channel: 0–15
                int program = event.instrument;      // instrument number 0–127

                // Program change (select instrument)
                ShortMessage programChange = new ShortMessage();
                programChange.setMessage(ShortMessage.PROGRAM_CHANGE, channel, program, 0);
                track.add(new MidiEvent(programChange, tickStart));

                // Note on
                ShortMessage noteOn = new ShortMessage();
                noteOn.setMessage(ShortMessage.NOTE_ON, channel, event.note, event.velocity);
                track.add(new MidiEvent(noteOn, tickStart));

                // Note off
                ShortMessage noteOff = new ShortMessage();
                noteOff.setMessage(ShortMessage.NOTE_OFF, channel, event.note, 0);
                track.add(new MidiEvent(noteOff, tickEnd));
            }

            // Write sequence to file
            File file = new File(filename);
            MidiSystem.write(sequence, 1, file);
            System.out.println("MIDI file saved to: " + file.getAbsolutePath());

        } catch (InvalidMidiDataException | IOException e) {
            e.printStackTrace();
        }
    }
}

