public class Solution {

    public static void main(String[] args) {
        playScalePiano();
        MidiPlayer.saveToFile("playScalePiano.mid");
        MidiPlayer.playNow();
        chord(60, 100, 0, 300, 4, 12);
        MidiPlayer.saveToFile("chord.mid");
        MidiPlayer.playNow();
        majorChord(60, 100, 0, 300);
        MidiPlayer.saveToFile("majorChord.mid");
        MidiPlayer.playNow();
        playCadence();
        MidiPlayer.saveToFile("playCadence.mid");
        MidiPlayer.playNow();
        playCanon();
        MidiPlayer.saveToFile("playCanon.mid");
        MidiPlayer.playNow();
        playArpeggio(40, 120, 0, 400, 1);
        MidiPlayer.saveToFile("playArpeggio.mid");
        MidiPlayer.playNow();
        albinoniAdagio();
        MidiPlayer.saveToFile("adagio.mid");
        MidiPlayer.playNow();
        MidiPlayer.shutdown();
    }

    public static void playScalePiano() {
        for (int i = 0; i < Tasks.SIMPLE_SCALE.length; i++) {
            int note = Tasks.SIMPLE_SCALE[i];
            MidiPlayer.registerNote(note, 100, i * 200, 200);
        }
    }

    /**
     *
     * @param note passed to registerNote
     * @param velocity passed to registerNote
     * @param startTimeMs passed to registerNote
     * @param durationMs passed to registerNote
     * @param chordNotes relative change in halftones to the parameter "note"
     */
    public static void chord(int note, int velocity, long startTimeMs, long durationMs, int... chordNotes) {
        MidiPlayer.registerNote(note, velocity, startTimeMs, durationMs);
        for (int chordNote: chordNotes) {
            MidiPlayer.registerNote(note + chordNote, velocity, startTimeMs, durationMs);
        }
    }

    /**
     * Plays a major chord using the note as base tone.
     * @param note base note
     * @param velocity passed to registerNote
     * @param startTimeMs passed to registerNote
     * @param durationMs passed to registerNote
     */
    public static void majorChord(int note, int velocity, long startTimeMs, long durationMs) {
        chord(note, velocity, startTimeMs, durationMs, 4, 7, 12);
    }

    public static void playCadence() {
        for (int i = 0; i < Tasks.SIMPLE_CADENCE.length; i++) {
            int currNote = Tasks.SIMPLE_CADENCE[i];
            MidiPlayer.registerNote(currNote - 12, 100, i*500, 500, 35);
            majorChord(currNote, 100, i*500, 500);
        }
    }

    public static void playCanon() {
        playCanon(16000);
    }

    public static void playCanon(int delayMs) {
        if (delayMs < 0){
            return;
        }
        for (int i = 0; i < Tasks.CANON_MELODY.length; i++) {
            int note = Tasks.CANON_MELODY[i];
            MidiPlayer.registerNote(note, 100, i * 500 + delayMs, 500);
        }
        playCanon(delayMs - 4000);
    }

    public static void playArpeggio(int note, int velocity, long startTimeMs, long duration, int instrument) {
        if (velocity < 5) {
            return;
        }
        MidiPlayer.registerNote(note, velocity, startTimeMs, duration, instrument);
        playArpeggio(note + 5, (int) (velocity / 1.3), startTimeMs + 400, duration, instrument);
    }

    // ------------------------------------
    // Below here: helper methods for the custom song.
    // It's the Albinoni Adagio

    static final long QUARTER_NOTE_LEN_MS = 700;
    static final long EIGHTH_NOTE_LEN_MS = QUARTER_NOTE_LEN_MS / 2;
    static final long SIXTEENTH_NOTE_LEN_MS = EIGHTH_NOTE_LEN_MS / 2;
    static final long THIRYTWOTHS_NOTE_LEN_MS = SIXTEENTH_NOTE_LEN_MS / 2;
    static long[] BAR_TIMES = new long[8];

    static final int BASS_INSTUMENT = 33;
    static final int SECONDARY_INSTRUMENT = 76;
    static final int PRIMARY_INSTRUMENT = 73;

    public static void albinoniAdagio() {
        for (int i = 0; i < BAR_TIMES.length; i++) {
            BAR_TIMES[i] = QUARTER_NOTE_LEN_MS * i * 3;
        }
        addBassPart();
        addSecondaryMelody();
        addMainMelody();
    }

    static final int[] BASS_NOTES = {31, 29, 27, 26, 24, 25, 26, 31};
    public static void addBassPart() {
        int totalNotes = 0;
        for (int i = 0; i < BASS_NOTES.length; i++) {
            int currentNote = BASS_NOTES[i];
            MidiPlayer.registerNote(currentNote, 70, totalNotes*QUARTER_NOTE_LEN_MS, QUARTER_NOTE_LEN_MS - 50, BASS_INSTUMENT);
            totalNotes++;
            MidiPlayer.registerNote(currentNote + 12, 70, totalNotes*QUARTER_NOTE_LEN_MS, QUARTER_NOTE_LEN_MS - 50, BASS_INSTUMENT);
            totalNotes++;
            MidiPlayer.registerNote(currentNote, 70, totalNotes*QUARTER_NOTE_LEN_MS, QUARTER_NOTE_LEN_MS - 50, BASS_INSTUMENT);
            totalNotes++;
        }
    }

    /**
     * I need this method because I don't want to specify every note on its own but I also don't want to calculate it based on a common base note (as in the chord()-function from the homework)
     */
    public static void customChord(int velocity, long startTimeMs, long durationMs, int instrument, int... chordNotes) {
        for (int note: chordNotes) {
            MidiPlayer.registerNote(note, velocity, startTimeMs, durationMs, instrument);
        }
    }

    public static void addSecondaryMelody() {
        // First two bars have repeating tone
        customChord(90, BAR_TIMES[0], QUARTER_NOTE_LEN_MS * 6 - 100, SECONDARY_INSTRUMENT, 58, 62, 67);
        // Second two bars have the same tone as well
        customChord(80, BAR_TIMES[2], QUARTER_NOTE_LEN_MS * 6 - 100, SECONDARY_INSTRUMENT, 58, 63);
        // Bar 5
        customChord(70, BAR_TIMES[4], QUARTER_NOTE_LEN_MS * 3 - 100, SECONDARY_INSTRUMENT, 63, 69);
        // Bar 6
        customChord(60, BAR_TIMES[5], QUARTER_NOTE_LEN_MS * 3 - 100, SECONDARY_INSTRUMENT, 64, 67);
        // Bar 7
        customChord(60, BAR_TIMES[6], QUARTER_NOTE_LEN_MS * 3 - 100, SECONDARY_INSTRUMENT, 62);
        customChord(60, BAR_TIMES[6] + 2*QUARTER_NOTE_LEN_MS, QUARTER_NOTE_LEN_MS - 100, SECONDARY_INSTRUMENT, 60);
        // Bar 8
        customChord(80, BAR_TIMES[7], QUARTER_NOTE_LEN_MS * 3 - 100, SECONDARY_INSTRUMENT, 58, 62);
    }

    /**
     * There is a repeating element where the melody rises, this automates that.
     */
    public static void risingMelody(int velocity, long startTimeMs, long lastDurationMs, int instrument, int note1, int note2, int note3) {
        long currentTime = startTimeMs;
        MidiPlayer.registerNote(note1, velocity, currentTime, THIRYTWOTHS_NOTE_LEN_MS, instrument);
        currentTime += THIRYTWOTHS_NOTE_LEN_MS;
        MidiPlayer.registerNote(note2, velocity, currentTime, THIRYTWOTHS_NOTE_LEN_MS, instrument);
        currentTime += THIRYTWOTHS_NOTE_LEN_MS;
        MidiPlayer.registerNote(note3, velocity, currentTime, lastDurationMs, instrument);
    }

    public static void addMainMelody() {
        // starts in bar 3
        risingMelody(100, BAR_TIMES[2], QUARTER_NOTE_LEN_MS + EIGHTH_NOTE_LEN_MS + SIXTEENTH_NOTE_LEN_MS + THIRYTWOTHS_NOTE_LEN_MS, PRIMARY_INSTRUMENT, 67, 69, 70);
        // note shortly before the end of bar 3
        MidiPlayer.registerNote(67, 100, BAR_TIMES[3]-QUARTER_NOTE_LEN_MS, QUARTER_NOTE_LEN_MS - 50, PRIMARY_INSTRUMENT);
        // bar 4 is one long note
        MidiPlayer.registerNote(67, 100, BAR_TIMES[3], QUARTER_NOTE_LEN_MS * 3 - 50, PRIMARY_INSTRUMENT);

        // bar 5 starts with a rising note that is held for the rest of the bar
        risingMelody(110, BAR_TIMES[4], 2 * QUARTER_NOTE_LEN_MS + SIXTEENTH_NOTE_LEN_MS + THIRYTWOTHS_NOTE_LEN_MS, PRIMARY_INSTRUMENT, 69, 70, 72);

        // bar 6 has a variation on the rising melody
        risingMelody(100, BAR_TIMES[5], 2 * QUARTER_NOTE_LEN_MS + SIXTEENTH_NOTE_LEN_MS + THIRYTWOTHS_NOTE_LEN_MS, PRIMARY_INSTRUMENT, 70, 69, 70);

        // bar 7 is the most exciting one with a repeat of the variation in bar 6 and then an end pattern
        risingMelody(90, BAR_TIMES[6], QUARTER_NOTE_LEN_MS + SIXTEENTH_NOTE_LEN_MS + THIRYTWOTHS_NOTE_LEN_MS + EIGHTH_NOTE_LEN_MS, PRIMARY_INSTRUMENT, 69, 67, 69);
        // there are two short notes in the end
        MidiPlayer.registerNote(67, 80, BAR_TIMES[7] - QUARTER_NOTE_LEN_MS, EIGHTH_NOTE_LEN_MS, PRIMARY_INSTRUMENT);
        MidiPlayer.registerNote(66, 80, BAR_TIMES[7] - EIGHTH_NOTE_LEN_MS, EIGHTH_NOTE_LEN_MS, PRIMARY_INSTRUMENT);

        // bar 8 is boring
        MidiPlayer.registerNote(67, 90, BAR_TIMES[7], QUARTER_NOTE_LEN_MS * 3, PRIMARY_INSTRUMENT);

    }
}

