import Prog1Tools.IOTools;

public class CesarCipher {

    public static void main(String[] args) {
        int length = IOTools.readInt("Länge: ");
        char[] code = new char[length];

        for (int i = 0; i < code.length; i++) {
            code[i] = IOTools.readChar("Stelle " + i + ": ");
        }

        int shift = 0;
        do {
            shift = IOTools.readInt("Verschiebung: ");
        } while (shift < -25 || shift > 25);


        // Cipher Loop
        for (int i = 0; i < code.length; i++) {
            char input = code[i];
            boolean isUppercase = input > 64 && input < 91;
            boolean isLowercase = input > 96 && input < 123;

            if (!isUppercase && !isLowercase) {
                System.out.println(i + ": Char ist kein Buchstabe, wird nicht geändert");
                continue;
            }


            char output = (char) (input + shift);
            if ((isUppercase && output < 65) || (isLowercase && output < 97)) {
                // We wrapped around to the negative
                output += 26;
                System.out.println(i + ": Char wurde +26 gerechnet");
            } else if ((isUppercase && output > 90) || (isLowercase && output > 122)) {
                // We wrapped around to the positive
                output -= 26;
                System.out.println(i + ": Char wurde -26 gerechnet");
            }
            code[i] = output;
        }

        // Output Loop
        System.out.println("Output: ");
        for (int i = 0; i < code.length; i++) {
            System.out.print(code[i]);
        }
        System.out.println();

    }
}

