        long loopDuration = endTime - startTime;

        startTime = System.currentTimeMillis();
        long sumGauss = (n * (n+1)) / 2;
        endTime = System.currentTimeMillis();
        long gaussDuration = endTime - startTime;

        if (sumLoop != sumGauss) {
