            System.out.println("Im Ernst, das sollte nie passieren, wahrscheinlich hat der Code einen Fehler");
            System.out.println("Loop: " + sumLoop + ", Gauss: " + sumGauss);
        } else {
            System.out.println("Die Summe ist: " + sumGauss);
        }

        System.out.println("Dauer der Loop (ms): " + loopDuration);
        System.out.println("Dauer der Summenformel (ms): " + gaussDuration);
    }

}

