    static int routeCounter = 0;
    static int schedRideCounter = 0;
    static int vehicleCounter = 0;
    private enum VehicleType {SIMPLE_BUS, DOUBLE_DECKER, FERRY, LIGHT_RAIL, TRAM}
    static final int repeatsPerVehicle = 100;

    private static void addSchedulesForRoute(Station[] stations, int numVehicles, StationType stationType, VehicleType vt) {
        Vehicle time_checker = null;
        switch (vt) {
            case SIMPLE_BUS:
                time_checker = new SimpleBus(1, stations[0].getLocation());
                break;
            case DOUBLE_DECKER:
                time_checker = new DoubleDecker(1, stations[0].getLocation());
                break;
            case FERRY:
                time_checker = new Ferry(1, stations[0].getLocation());
                break;
            case LIGHT_RAIL:
                time_checker = new LightRail(1, stations[0].getLocation());
                break;
            case TRAM:
                time_checker = new Tram(1, stations[0].getLocation());
                break;
        }

        Station[] reversedStations = reverse(stations);

        Route normalRoute = new Route(routeCounter++, stations, stationType);
        Route reversedRoute = new Route(routeCounter++, reversedStations, stationType);
        StateKeeper.addRoute(normalRoute);
        StateKeeper.addRoute(reversedRoute);

        // Just a test ride to figure out total duration....
        ScheduledRide sr = new ScheduledRide(0, time_checker, normalRoute, 0);
        long duration = sr.getFinishTime(); // Since it starts at 0 this is the duration.

        for (int i = 0; i < numVehicles; i++) {
            Vehicle v = null;
            switch (vt) {
                case SIMPLE_BUS:
                    v = new SimpleBus(vehicleCounter++, stations[0].getLocation());
                    break;
                case DOUBLE_DECKER:
                    v = new DoubleDecker(vehicleCounter++, stations[0].getLocation());
                    break;
                case FERRY:
                    v = new Ferry(vehicleCounter++, stations[0].getLocation());
                    break;
                case LIGHT_RAIL:
                    v = new LightRail(vehicleCounter++, stations[0].getLocation());
                    break;
                case TRAM:
                    v = new Tram(vehicleCounter++, stations[0].getLocation());
                    break;
            }

            v.setLocation(stations[0].getLocation());
            StateKeeper.addVehicle(v);

            long staggeredStartTime = (long) ((2.0 * duration) * (i / (numVehicles-1.0)));

            for (int j = 0; j < repeatsPerVehicle; j++) {
                ScheduledRide towards = new ScheduledRide(schedRideCounter++, v, normalRoute, staggeredStartTime + (j * 2 * duration));
                StateKeeper.addScheduledRide(towards);
                StateKeeper.addScheduledRide(new ScheduledRide(schedRideCounter++, v, reversedRoute, towards.getFinishTime()));
            }
        }
    }

    private static void addPassengers() {
        Station[] allStation = StateKeeper.getStations();
        int passengerCount = 0;
        for (Station s: allStation) {
            for (int i = 0; i < 3; i++) {
                Station target = allStation[(int) (allStation.length * Math.random())];
                s.addPassenger(new Passenger(++passengerCount, "P" + passengerCount + target.getName(), target, (int) (5000 * Math.random()), s, TicketType.getRandom()));
            }
        }
    }
