package model;

public interface HasLocation {
    public Location getLocation();
}

package model.schedules;

import bvg.StateKeeper;
import model.HasUpdate;
import model.Location;
import model.PassengerHolder;
import model.passenger.Passenger;
import model.stations.Station;
import model.vehicles.Vehicle;

public class ScheduledRide implements HasUpdate {
    int id;
    private final Vehicle v;
    private final Route r;
    private final long startTime;

    public ScheduledRide(int id, Vehicle v, Route r, long startTime) {
        this.id = id;
        this.v = v;
        this.r = r;
        this.startTime = startTime;
    }

    public int getId() {
        return id;
    }

    public Vehicle getV() {
        return v;
    }

    public Route getRoute() {
        return r;
    }

    public long getStartTime() {
        return startTime;
    }

    public long getFinishTime() {
        ScheduledRideStop[] allStops = getAllStops();
        return allStops[allStops.length-1].getTime();
    }


    public boolean willReachStation(Station s) {
        for (ScheduledRideStop stop: getAllStops()) {
            if (stop.getStation().equals(s) && stop.getTime() >= StateKeeper.getCurrentTime()) {
                return true;
            }
        }
        return false;
    }

    /**
     * Get all the Stops that will happen in a Ride.
     * To calculate that, you need to know:
     * - the start time of the ride (which is an instance variable of this class)
     * - the speed of the vehicle (which is saved as an instance variable of the Vehicle)
     * - the stops that will happen in the route and their respective distance to the previous stop
     * @return
     */
    public ScheduledRideStop[] getAllStops() {
        double speed = v.getMaxSpeed();

        ScheduledRideStop[] stops = new ScheduledRideStop[r.getStations().length];
        stops[0] = new ScheduledRideStop(r.getStations()[0], startTime, this);
        for (int i = 1; i < r.getStations().length; i++) {
            Station nextStation = r.getStations()[i];
            double distanceToNextStation = Location.getDistanceBetween(r.getStations()[i-1].getLocation(), nextStation.getLocation());
            // This next line explicitly rounds up and converts to long since we measure time in exact increments / integers...
            long timeToNextStation = (long) Math.ceil(distanceToNextStation / speed);
            // Save the stop to the array
            stops[i] = new ScheduledRideStop(nextStation, stops[i-1].getTime() + timeToNextStation, this);
        }
        return stops;
    }



    @Override
    public String toString() {
        return "ScheduledRide{" +
                "id=" + id +
                ", v=" + v +
                ", r=" + r +
                ", startTime=" + startTime +
                '}';
    }

    @Override
    public void update() {
        int currentTime = StateKeeper.getCurrentTime();
        // Easy exit: the ride hasn't started yet.
        if (currentTime < this.startTime) {
            return;
        }
        ScheduledRideStop[] stops = getAllStops();

        // Another easy exit: the ride has already stopped.
        if (currentTime > stops[stops.length-1].getTime()) {
            return;
        }

        // :( we actually need to do some work
        for (int i = 0; i < stops.length; i++) {
            ScheduledRideStop s = stops[i];
            if (s.getTime() == currentTime) {
                // We are currently at this station!
                if (Location.getDistanceBetween(v.getLocation(), s.getLocation()) > 0.1) {
                    System.err.println("Vehicle is supposed to be at station, but is pretty far away.... (next lines are vehicle and station)");
                    System.out.println(v);
                    System.out.println(s);
                }

                v.setLocation(s.getLocation().copy());
                // Now we can ask the passengers to move
                // Start with the passenger in the vehicle
                for (Passenger p: v.getPassengers()) {
                    if (p.offerToMoveTo(s.getStation(), v)){
                        PassengerHolder.transferBetween(p, v, s.getStation());
                    }
                }
                for (Passenger p: s.getStation().getPassengers()) {
                    if (v.getPassengers().length < v.getMaxPassengerCapacity() && p.offerToMoveTo(v, s.getStation())){
                        PassengerHolder.transferBetween(p, s.getStation(), v);
                    }
                }
                // Stop moving for one iteration...
                return;
            }
            if (s.getTime() > currentTime) {
                // We are currently moving towards this station.
                // This works because the ScheduledRideStops are sorted
                v.getLocation().moveTowards(stops[i].getLocation(), v.getMaxSpeed());
                return;
            }
        }
    }
}

