import javax.swing.*;
import java.awt.*;
import java.util.Hashtable;

public class Main {
    static Color[] passengerColors = new Color[100];

    static {
        for (int i = 0; i < passengerColors.length; i++) {
            float hue = i / 100.0f;       // even spread of hues
            float saturation = 0.8f;      // fairly vivid
            float brightness = 0.9f;      // fairly bright
            passengerColors[i] = Color.getHSBColor(hue, saturation, brightness);
        }
    }

    public static void main(String[] args) {
        ScenarioHelper.scenarioToStateKeeper("bvg");

        SwingUtilities.invokeLater(() -> {
            int windowWidth = 900;
            int windowHeight = 700;
            int margin = 50;

            JFrame frame = new JFrame("BVG Map Viewer");
            frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
            frame.setSize(windowWidth, windowHeight);
            frame.setLayout(new BorderLayout());

            // --- Map panel ---
            JPanel mapPanel = new JPanel() {
                @Override
                protected void paintComponent(Graphics g) {
                    super.paintComponent(g);
                    Graphics2D g2 = (Graphics2D) g;
                    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

                    double[] b = StateKeeper.getBounds();
                    double minX = b[0];
                    double minY = b[1];
                    double maxX = b[2];
                    double maxY = b[3];

                    int w = getWidth() - 2 * margin;
                    int h = getHeight() - 2 * margin;
                    double scaleX = w / (maxX - minX);
                    double scaleY = h / (maxY - minY);
                    double scale = Math.min(scaleX, scaleY);

                    java.util.function.Function<Double, Integer> transformX =
                            x -> (int) ((x - minX) * scale + margin);
                    java.util.function.Function<Double, Integer> transformY =
                            y -> (int) ((maxY - y) * scale + margin); // invert Y for display

                    g2.setFont(new Font("SansSerif", Font.PLAIN, 9));

                    // Draw stations
                    for (Station s : StateKeeper.getStations()) {
                        g2.setColor(Color.DARK_GRAY);
                        Location loc = s.getLocation();
                        if (loc == null) continue;
                        int x = transformX.apply(loc.getX());
                        int y = transformY.apply(loc.getY());
                        g2.fillOval(x - 2, y - 2, 4, 4);
                        g2.drawString(s.getName(), x + 5, y);

                        for (int i = 0; i < s.getPassengers().length; i++) {
                            Passenger p = s.getPassengers()[i];
                            if (p.getDestination().equals(s)) {
                                // Passenger has arrived!
                                g2.setColor(Color.GREEN);
                            } else {
                                g2.setColor(passengerColors[Math.abs(p.hashCode()) % passengerColors.length]);
                            }

                            int px = x - 3 - (i + 1) * 5;
                            int py = y - 3 - (i + 1) * 5;

                            g2.fillRect(px, py, 4, 4);
                            g2.drawString(p.getName(), px - 2, py - 2);
                            g2.setColor(Color.BLACK);
                            g2.drawRect(px, py, 4, 4);
                        }
                    }

                    for (Vehicle v : StateKeeper.getVehicles()) {

                        switch (v.getClass().getSimpleName()) {
                            case "SimpleBus" ->
                                    g2.setColor(new Color(255, 204, 0));
                            case "DoubleDecker" ->
                                    g2.setColor(new Color(255, 184, 28));
                            case "Tram" ->
                                    g2.setColor(new Color(255, 230, 77));
                            case "LightRail" ->
                                    g2.setColor(new Color(255, 220, 40));
                            case "Ferry" ->
                                    g2.setColor(new Color(0, 102, 204));
                            default ->
                                    g2.setColor(new Color(120, 120, 120));
                        }

                        Location loc = v.getLocation();
                        if (loc == null) continue;
                        int x = transformX.apply(loc.getX());
                        int y = transformY.apply(loc.getY());

                        Color fillColor = g2.getColor(); // remember current fill color
                        g2.fillRect(x - 3, y - 3, 6, 6); // fill the vehicle shape

                        g2.setColor(Color.BLACK);
                        g2.drawRect(x - 3, y - 3, 6, 6);
                        g2.drawString("V" + v.getId(), x + 6, y);

                        for (int i = 0; i < v.getPassengers().length; i++) {
                            Passenger p = v.getPassengers()[i];
                            g2.setColor(passengerColors[Math.abs(p.hashCode()) % passengerColors.length]);

                            int px = x - 3 - (i + 1) * 5;
                            int py = y - 3 - (i + 1) * 5;

                            g2.fillRect(px, py, 4, 4);
                            g2.drawString(p.getName(), px - 2, py - 2);

                            g2.setColor(Color.BLACK);
                            g2.drawRect(px, py, 4, 4);
                        }

                    }
                }
            };

            frame.add(mapPanel, BorderLayout.CENTER);

            // --- Control panel (bottom) ---
            JPanel controlPanel = new JPanel(new FlowLayout(FlowLayout.CENTER));
            JLabel sliderLabel = new JLabel("Update every:");

            JSlider delaySlider = new JSlider(10, 5000, 1000); // range: 0.01s - 5s
            delaySlider.setPreferredSize(new Dimension(300, 50));

            Hashtable<Integer, JLabel> labelTable = new Hashtable<>();
            labelTable.put(10, new JLabel("0.01s"));
            labelTable.put(1000, new JLabel("1s"));
            labelTable.put(2000, new JLabel("2s"));
            labelTable.put(5000, new JLabel("5s"));
            delaySlider.setLabelTable(labelTable);
            delaySlider.setPaintLabels(true);
            delaySlider.setPaintTicks(true);
            delaySlider.setMajorTickSpacing(1000);
            delaySlider.setMinorTickSpacing(100);
            delaySlider.setSnapToTicks(false);

            JButton resetButton = new JButton("Reset Update Interval");
            JButton pauseResumeButton = new JButton("Pause Updates");

            controlPanel.add(sliderLabel);
            controlPanel.add(delaySlider);
            controlPanel.add(resetButton);
            controlPanel.add(pauseResumeButton);

            frame.add(controlPanel, BorderLayout.SOUTH);

            // --- Timer setup ---
            int initialDelay = delaySlider.getValue();
            Timer timer = new Timer(initialDelay, e -> {
                StateKeeper.update();
                mapPanel.repaint();
            });
            timer.start();

            // Adjust timer delay live when slider changes
            delaySlider.addChangeListener(e -> {
                int newDelay = delaySlider.getValue();
                timer.setDelay(newDelay);
                timer.setInitialDelay(newDelay);
            });

            // Reset button restores 1 second
            resetButton.addActionListener(e -> {
                delaySlider.setValue(1000);
                timer.setDelay(1000);
                timer.setInitialDelay(1000);
            });

            // Pause / Resume button toggles timer state
            pauseResumeButton.addActionListener(e -> {
                if (timer.isRunning()) {
                    timer.stop();
                    pauseResumeButton.setText("Resume Updates");
                } else {
                    timer.start();
                    pauseResumeButton.setText("Pause Updates");
                }
            });

            frame.setVisible(true);
        });
    }
}

