package model;

import model.passenger.Passenger;
public abstract class PassengerHolder {
    Passenger[] passengers = new Passenger[0];

    public Passenger[] getPassengers() {
        return passengers;
    }

    public void addPassenger(Passenger p) {
        Passenger[] newPassengers = new Passenger[passengers.length+1];
        System.arraycopy(passengers, 0 , newPassengers, 0, passengers.length);
        newPassengers[passengers.length] = p;
        passengers = newPassengers;
    }

    public boolean removePassenger(Passenger p) {
        int indexToRemove = -1;
        for (int i = 0; i < passengers.length; i++) {
            if (passengers[i].equals(p)) {
                indexToRemove = i;
                break;
            }
        }
        if (indexToRemove == -1) {
            System.err.println("This Passenger not in PassengerHolder: " + p);
            System.err.println("... this Holder is: " + this);
            return false;
        }
        Passenger[] newPassengers = new Passenger[passengers.length - 1];

        System.arraycopy(passengers, 0, newPassengers, 0, indexToRemove);
        System.arraycopy(passengers, indexToRemove + 1, newPassengers, indexToRemove, passengers.length - indexToRemove - 1);

        passengers = newPassengers;
        return true;
    }

    public Passenger getPassengerById(int id) {
        for (Passenger p: passengers) {
            if (p.getId() == id) {
                return p;
            }
        }
        return null;
    }

    public static void transferBetween(Passenger p, PassengerHolder from, PassengerHolder to) {
        boolean isRemoved = from.removePassenger(p);
        if (isRemoved) {
            to.addPassenger(p);
        }
    }
}

