package model;

import java.util.Objects;

/**
 * Represents the (current) Location of something in 2D Space.
 * There is a static method getDistanceBetween() that calucaltes the distance between two points.
 */
public class Location {
    private double x;
    private double y;

    public Location(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getY() {
        return y;
    }

    public void setY(double y) {
        this.y = y;
    }

    public double getX() {
        return x;
    }

    public void setX(double x) {
        this.x = x;
    }

    @Override
    public String toString() {
        return "Location{ x=" + x + ", y=" + y + '}';
    }

    /**
     * Euclid Distance between two Locations
     * @param l1 first location
     * @param l2 second location
     * @return Euclid Distance between two locations
     */
    public static double getDistanceBetween(Location l1, Location l2) {
        double dx = l1.getX() - l2.getX();
        double dy = l1.getY() - l2.getY();
        return Math.sqrt(dx * dx + dy * dy);
    }

    public void moveTowards(Location other, double speed) {
        double dx = other.getX() - this.x;
        double dy = other.getY() - this.y;

        double distance = Math.sqrt(dx * dx + dy * dy);

        // If we're already at the destination or speed is zero, do nothing
        if (distance == 0 || speed <= 0) {
            return;
        }

        // If we can reach or exceed the target this step, move directly there
        if (speed >= distance) {
            this.x = other.getX();
            this.y = other.getY();
            return;
        }

        // Normalize direction vector (dx, dy)
        double ratio = speed / distance;
        //double ratio = distance / speed;
        this.x += dx * ratio;
        this.y += dy * ratio;
    }

    public Location copy() {
        return new Location(this.x, this.y);
    }

    @Override
    public boolean equals(Object o) {
        if (o == null || getClass() != o.getClass()) return false;
        Location location = (Location) o;
        return Double.compare(x, location.x) == 0 && Double.compare(y, location.y) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);
    }
}

