package model.passenger;

import bvg.StateKeeper;
import model.PassengerHolder;
import model.schedules.Route;
import model.schedules.ScheduledRide;
import model.schedules.ScheduledRideStop;
import model.stations.Station;
import model.vehicles.IsRapidTransit;
import model.vehicles.Vehicle;

import javax.swing.plaf.nimbus.State;

public class Passenger {
    int id;
    String name;
    Station destination;
    Station startLocation;
    long travelStart;
    TicketType ticketType;

    public Passenger(int id, String name, Station destination, long travelStart, Station startLocation, TicketType ticketType) {
        this.id = id;
        this.name = name;
        this.destination = destination;
        this.travelStart = travelStart;
        this.startLocation = startLocation;
        this.ticketType = ticketType;
    }

    public int getId() {
        return id;
    }

    public String getName() {
        return name;
    }

    public Station getDestination() {
        return destination;
    }

    public long getTravelStart() {
        return travelStart;
    }

    public Station getStartLocation() {
        return startLocation;
    }

    public TicketType getTicketType() {
        return ticketType;
    }

    @Override
    public String toString() {
        return "Passenger{" +
                "id=" + id +
                ", name='" + name + '\'' +
                ", destination=" + destination +
                ", travelStart=" + travelStart +
                ", startLocation=" + startLocation +
                ", ticketType=" + ticketType +
                '}';
    }

    /**
     * Return whether the passenger would like to move from the current PassengerHolder to this one.
     * Can happen because a Vehicle passed the Station the Passenger is currently in, or the Vehicle passed a Station.
     * Return whether the transfer should happen, the actual transfer will happen somewhere else.
     * @return
     */
    public boolean offerToMoveTo(PassengerHolder maybeNew, PassengerHolder current) {
        if (StateKeeper.getCurrentTime() < travelStart) {
            return false;
        }

        // Am I already at my destination?
        if (current.equals(destination)) {
            return false;
        }

        // Can I get off at my destination?
        if (maybeNew.equals(destination)) {
            return true;
        }

        // Am I in a Vehicle that will reach my Destination?
        if (current instanceof Vehicle) {
            Vehicle v = (Vehicle) current;
            if (StateKeeper.getCurrentScheduledRideOfVehicle(v).willReachStation(destination)) {
                return false;
            }
            // I am in a Vehicle that will not reach my destination!
            return Math.random() < (0.2 * StateKeeper.countRoutesByStation((Station) maybeNew));
        }

        // I am in a Station.
        // Will the vehicle reach my Destination?
        Vehicle v = (Vehicle) maybeNew;
        if (!canEnterVehicle(v)) {
            return false;
        }

        if (StateKeeper.getCurrentScheduledRideOfVehicle(v).willReachStation(destination)) {
            return true;
        }

        // I am in a Station and the Vehicle will not reach my Destination
        return Math.random() > 0.1;

    }

    boolean canEnterVehicle(Vehicle v) {
        if (this.ticketType == TicketType.ALL) {
            return true;
        }
        if (v instanceof IsRapidTransit) {
            return false;
        }
        return true;
    }
}

