import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Collectors;

public class ScenarioWriter {

    public static void main(String[] args) {
        simpleScenario();
        saveStateToScenarioFile("simple");
        simpleScenarioWithErrors();
        saveStateToScenarioFile("simpleWithErrors");
        complexScenario();
        saveStateToScenarioFile("complex");
    }

    private static void simpleScenario() {
        StateKeeper.addVehicle(new SimpleBus(0, new Location(0,0)));
        StateKeeper.addVehicle(new DoubleDecker(1, new Location(0,0)));

        // Stations are numbered [0,9]
        Station[] allStations = new Station[10];
        for (int i = 0; i < allStations.length; i++) {
            Station newStation = new Station(i, "Station y-Axis #" + i, new StationType[]{StationType.STREET, StationType.WATER, StationType.RAIL}, new Location(0, i*10));
            StateKeeper.addStation(newStation);
            allStations[i] = newStation;
        }

        // add an initial route with all Stations
        Route r0 = new Route(0, allStations, StationType.STREET);
        StateKeeper.addRoute(r0);
        // reverse the Array to add a reverse route
        Station[] reversedStations = new Station[allStations.length];
        int counter = 0;
        for (int i = allStations.length - 1; i >= 0; i--) {
            reversedStations[counter++] = allStations[i];
        }
        Route r1 = new Route(1, reversedStations, StationType.STREET);
        StateKeeper.addRoute(r1);

        StateKeeper.addScheduledRide(new ScheduledRide(0, StateKeeper.getVehicleById(0), r0, 0));
        StateKeeper.addScheduledRide(new ScheduledRide(1, StateKeeper.getVehicleById(1), r1, 0));
    }

    private static void simpleScenarioWithErrors() {
        simpleScenario();
        // Add a duplicate ID Vehicle
        StateKeeper.addVehicle(new Tram(0, new Location(0,0)));

        // Add a Water Station to a route that is on the street
        Station waterStation = new Station(10, "Water Station", new StationType[]{StationType.WATER}, new Location(100, 100));
        StateKeeper.addStation(waterStation);
        Station[] stations = new Station[]{StateKeeper.getStationById(0), StateKeeper.getStationById(1), waterStation};
        StateKeeper.addRoute(new Route(2, stations, StationType.STREET));
    }

    private static void complexScenario() {
        // Add 10 Vehicles of each type, a Grid of Stations,
        int counter = 0;
        for (int i = 0; i < 10; i++) {
            StateKeeper.addVehicle(new DoubleDecker(counter++, new Location(0,0)));
            StateKeeper.addVehicle(new Ferry(counter++, new Location(0,0)));
            StateKeeper.addVehicle(new LightRail(counter++, new Location(0,0)));
            StateKeeper.addVehicle(new SimpleBus(counter++, new Location(0,0)));
            StateKeeper.addVehicle(new Tram(counter++, new Location(0,0)));
        }

        // Add a couple of Stations along a grid
        counter = 0;

        List<Station> diagonalRightUp = new ArrayList<>();
        List<Station> diagonalRightDown = new ArrayList<>();
        List<Station> randomWater = new ArrayList<>();
        List<Station> random2 = new ArrayList<>();


        for (int i = 0; i <= 100; i += 10) {
            for (int j = 0; j <= 100; j+= 10) {
                StationType[] types;
                if (j > 81) {
                    types = new StationType[]{StationType.WATER, StationType.STREET};
                } else if (j > 61) {
                    types = new StationType[]{StationType.STREET};
                } else if (j < 20) {
                    types = new StationType[]{StationType.RAIL, StationType.STREET};
                } else {
                    types = new StationType[]{StationType.STREET, StationType.RAIL};
                }
                Station s = new Station(counter++, String.format("Station %d %d", i, j), types, new Location(i,j));
                StateKeeper.addStation(s);
                if (i == j) {
                    diagonalRightUp.add(s);
                }
                if (i + j == 100) {
                    diagonalRightDown.add(s);
                }
                if (i + j % 20 == 0 && types[0] == StationType.WATER) {
                    randomWater.add(s);
                }
                if ((i > j && j % 20 == 0)) {
                    random2.add(s);
                }
            }
        }

        StateKeeper.addRoute(new Route(0, diagonalRightUp.toArray(new Station[0]), StationType.STREET));
        StateKeeper.addRoute(new Route(1, diagonalRightDown.toArray(new Station[0]), StationType.STREET));
        StateKeeper.addRoute(new Route(2, random2.toArray(new Station[0]), StationType.STREET));
        StateKeeper.addRoute(new Route(3, randomWater.toArray(new Station[0]), StationType.WATER));

        for (int i = 0; i < StateKeeper.getVehicles().length; i++) {
            Vehicle v = StateKeeper.getVehicles()[i];
            if (v.getAllowedStationType() == StationType.WATER) {
                StateKeeper.addScheduledRide(new ScheduledRide(i, v, StateKeeper.getRouteById(3), i * 100));
            } else if (v.getAllowedStationType() == StationType.STREET) {
                StateKeeper.addScheduledRide(new ScheduledRide(i, v, StateKeeper.getRouteById(i % 3), i * 100));
            }
        }
    }

    private static void saveStateToScenarioFile(String scenario) {
        try {
            Files.write(Path.of("scenarios", scenario + ".txt"), turnStateToString());
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    private static List<String> turnStateToString() {
        ArrayList<String> all = new ArrayList<>();
        Arrays.stream(StateKeeper.getVehicles()).map(ScenarioWriter::format).collect(Collectors.toCollection(() -> all));
        Arrays.stream(StateKeeper.getStations()).map(ScenarioWriter::format).collect(Collectors.toCollection(() -> all));
        Arrays.stream(StateKeeper.getRoutes()).map(ScenarioWriter::format).collect(Collectors.toCollection(() -> all));
        Arrays.stream(StateKeeper.getScheduledRides()).map(ScenarioWriter::format).collect(Collectors.toCollection(() -> all));
        StateKeeper.reset();
        return all;
    }

    private static String format(Vehicle v) {
        return String.format("vehicle,%s,%d,%s,%s",v.getClass().getSimpleName(), v.getId(), v.getLocation().getX(), v.getLocation().getY());
    }

    private static String format(Station s) {
        return String.format("station,%d,%s,%s,%s,%s,%s", s.getId(), s.getName(), s.getLocation().getX(), s.getLocation().getY(), s.getAllowedTypes().length,
                Arrays.stream(s.getAllowedTypes()).map(StationType::toString).collect(Collectors.joining(",")));
    }

    private static String format(Route r) {
        return String.format("route,%d,%s,%d,%s", r.getId(), r.getType().toString(), r.getStations().length , Arrays.stream(r.getStations()).map(it -> Integer.valueOf(it.getId()).toString()).collect(Collectors.joining(",")));
    }

    private static String format(ScheduledRide s) {
        return String.format("scheduledRide,%d,%d,%d,%d", s.getId(),s.getV().getId(), s.getRoute().getId(), s.getStartTime());
    }

}

package bvg;

import model.schedules.Route;
import model.schedules.ScheduledRide;
import model.schedules.ScheduledRideStop;
import model.stations.Station;
import model.stations.StationType;
import model.vehicles.Vehicle;

import java.util.Arrays;

public class Validator {

    public static boolean validateAll() {
        return validateRoutes() && validateStations() && validateVehicles() && validateScheduledRides() && validateVehicleSchedule();
    }

    private static boolean validateRoutes() {
        Route[] allRoutes = StateKeeper.getRoutes();
        for (int i = 0; i < allRoutes.length; i++) {
            Route r = allRoutes[i];

            // Check if all stations of a route have the type of the route
            StationType routeRequirement = r.getType();
            for (Station s: r.getStations()) {
                boolean stationHasType = false;
                for (StationType t: s.getAllowedTypes()) {
                    if (t.equals(routeRequirement)) {
                        stationHasType = true;
                        break;
                    }
                }
                if (!stationHasType) {
                    System.err.println("ERROR in Route " + r + "! Station " + s.getName() + " does not have Type " + routeRequirement + ". Instead, it has " + Arrays.toString(s.getAllowedTypes()));
                    return false;
                }
            }

            // Check if another route has the same ID
            int thisId = r.getId();
            for (int j = i+1; j < allRoutes.length; j++) {
                if (allRoutes[j].getId() == thisId) {
                    System.err.println("Problem! Two routes have the ID " + thisId);
                    return false;
                }
            }
        }
        return  true;
    }

    private static boolean validateScheduledRides() {
        // Check if the route has the correct vehicle and if its ID is unique.
        ScheduledRide[] allScheduledRides = StateKeeper.getScheduledRides();

        for (int i = 0; i < allScheduledRides.length; i++) {
            ScheduledRide current = allScheduledRides[i];
            StationType vehicleNeedsStation = current.getV().getAllowedStationType();
            if (vehicleNeedsStation != current.getRoute().getType()) {
                System.err.println("Problem! Route has other type than vehicle assigned to it in ScheduledRide");
                System.err.println(current);
                return false;
            }
            if (current.getStartTime() < 0) {
                System.err.println("Problem! Start time can not be negative!");
                System.err.println(current);
            }
            for (int j = i + 1; j < allScheduledRides.length; j++) {
                ScheduledRide other = allScheduledRides[j];
                if (current.getId() == other.getId()) {
                    System.err.println("Problem! Two ScheduledRides have the same id " + current.getId());
                    System.err.println(current);
                    System.err.println(other);
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean validateVehicles() {
        Vehicle[] allVehicles = StateKeeper.getVehicles();
        // Check if all the IDs are unique
        for (int i = 0; i < allVehicles.length; i++) {
            for (int j = i + 1; j < allVehicles.length; j++) {
                if (allVehicles[i].getId() == allVehicles[j].getId()) {
                    System.err.println("Problem! Two Vehicles have the ID " + allVehicles[i].getId());
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean validateStations() {
        Station[] allStations = StateKeeper.getStations();

        for (int i = 0; i < allStations.length; i++) {
            Station current = allStations[i];

            // Check if another station has the same location or the same id
            for (int j = i+1; j < allStations.length; j++) {
                Station other = allStations[j];
                if (current.getLocation().equals(other.getLocation())) {
                    System.err.println("Problem! Two stations have the same Location!: ");
                    System.err.println(current);
                    System.err.println(other);
                    return false;
                }
                if (current.getId() == other.getId()) {
                    System.err.println("Problem! Two stations have the same ID!: ");
                    System.err.println(current);
                    System.err.println(other);
                    return false;
                }
            }
        }
        return true;
    }

    private static boolean validateVehicleSchedule() {
        ScheduledRide[] allSchedules = StateKeeper.getScheduledRides();

        for (int i = 0; i < allSchedules.length; i++) {
            ScheduledRide current = allSchedules[i];
            Vehicle v = current.getV();
            ScheduledRideStop[] currentStops = current.getAllStops();
            long currentStart = currentStops[0].getTime();
            long currentEnd = currentStops[currentStops.length-1].getTime();

            for (int j = i + 1; j < allSchedules.length; j++) {
                ScheduledRide other = allSchedules[j];
                Vehicle otherVehicle = other.getV();
                if (v.equals(otherVehicle)) {
                    // We need to check if this vehicle is in use at the same time.
                    ScheduledRideStop[] otherStops = other.getAllStops();
                    long otherStart = otherStops[0].getTime();
                    long otherEnd = otherStops[otherStops.length - 1].getTime();

                    boolean overlap = (currentStart < otherEnd) && (currentEnd > otherStart);

                    if (overlap) {
                        System.err.println("Problem! The Vehicle " + v + " is in use at the same time for two schedules:");
                        System.err.println(current);
                        System.err.println(other);
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

