package bvg;

import model.Location;
import model.schedules.Route;
import model.schedules.ScheduledRide;
import model.stations.Station;
import model.stations.StationType;
import model.vehicles.DoubleDecker;
import model.vehicles.SimpleBus;
import model.vehicles.Vehicle;

import java.util.Arrays;

public class StateKeeper {

    private static Vehicle[] vehicles = new Vehicle[0];
    private static Station[] stations = new Station[0];
    private static Route[] routes = new Route[0];
    private static ScheduledRide[] scheduledRides = new ScheduledRide[0];

    public static void addVehicle(Vehicle v) {
        Vehicle[] newVehicles = new Vehicle[vehicles.length + 1];
        System.arraycopy(vehicles, 0, newVehicles, 0, vehicles.length);
        newVehicles[newVehicles.length - 1] = v;
        vehicles = newVehicles;
    }

    public static Vehicle getVehicleById(int id) {
        for (Vehicle v: vehicles) {
            if (v.getId() == id) {
                return v;
            }
        }
        System.err.println("The Vehicle with the ID " + id + " does not exist!");
        return null;
    }

    public static void addStation(Station s) {
        Station[] newStation = new Station[stations.length + 1];
        System.arraycopy(stations, 0, newStation, 0, stations.length);
        newStation[newStation.length - 1] = s;
        stations = newStation;
    }

    public static Station getStationById(int id) {
        for (Station s: stations) {
            if (s.getId() == id) {
                return s;
            }
        }
        System.err.println("The Station with the ID " + id + " does not exist!");
        return null;
    }

    public static Station getStationByName(String name) {
        for (Station s: stations) {
            if (s.getName().equals(name)) {
                return s;
            }
        }
        System.err.println("The Station with the Name " + name + " does not exist!");
        return null;
    }

    public static void addRoute(Route r) {
        Route[] newRoutes = new Route[routes.length + 1];
        System.arraycopy(routes, 0, newRoutes, 0, routes.length);
        newRoutes[newRoutes.length - 1] = r;
        routes = newRoutes;
    }

    public static Route getRouteById(int id) {
        for (Route r: routes) {
            if (r.getId() == id) {
                return r;
            }
        }
        System.err.println("The Station with the ID " + id + " does not exist!");
        return null;
    }

    public static void addScheduledRide(ScheduledRide r) {
        ScheduledRide[] newScheduledRides = new ScheduledRide[scheduledRides.length + 1];
        System.arraycopy(scheduledRides, 0, newScheduledRides, 0, scheduledRides.length);
        newScheduledRides[newScheduledRides.length - 1] = r;
        scheduledRides = newScheduledRides;
    }

    public static void printAllScheduledRides() {
        for (ScheduledRide r: scheduledRides) {
            System.out.println("ScheduledRide: " + r.getRoute());
            System.out.println(Arrays.toString(r.getAllStops()));
        }
    }

    public static void printAllVehicles() {
        for (Vehicle v: vehicles) {
            System.out.println(v);
        }
    }

    public static Vehicle[] getVehicles() {
        return vehicles;
    }

    public static Station[] getStations() {
        return stations;
    }

    public static Route[] getRoutes() {
        return routes;
    }

    public static ScheduledRide[] getScheduledRides() {
        return scheduledRides;
    }

    public static void reset() {
        vehicles = new Vehicle[0];
        stations = new Station[0];
        routes = new Route[0];
        scheduledRides = new ScheduledRide[0];
    }
}

package bvg;

import model.Location;
import model.schedules.Route;
import model.schedules.ScheduledRide;
import model.stations.Station;
import model.stations.StationType;
import model.vehicles.*;

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;
import java.util.List;
import java.util.stream.Stream;

public class ScenarioHelper {

    public static void scenarioToStateKeeper(String scenarioName) {
        String[][] strings = readScenario(scenarioName);
        for (String[] line: strings) {
            String type = line[0];
            switch (type) {
                case "vehicle":
                    addVehicleToState(line);
                    break;
                case "station":
                    addStationToState(line);
                    break;
                case "route":
                    addRouteToState(line);
                    break;
                case "scheduledRide":
                    addScheduledRideToState(line);
                    break;
            }
        }
    }

    private static void addVehicleToState(String[] line) {
        String className = line[1];
        int id = Integer.parseInt(line[2]);
        double x = Double.parseDouble(line[3]);
        double y = Double.parseDouble(line[4]);
        Location l = new Location(x,y);
        Vehicle v;
        switch (className) {
            case "DoubleDecker":
                v = new DoubleDecker(id, l);
                break;
            case "Ferry":
                v = new Ferry(id, l);
                break;
            case "LightRail":
                v = new LightRail(id, l);
                break;
            case "SimpleBus":
                v = new SimpleBus(id, l);
                break;
            case "Tram":
                v = new Tram(id, l);
                break;
            default:
                System.err.println("line can not be parsed: " + Arrays.toString(line));
                return;
        }
        StateKeeper.addVehicle(v);
    }

    private static void addStationToState(String[] line) {
        int id = Integer.parseInt(line[1]);
        String name = line[2];
        double x = Double.parseDouble(line[3]);
        double y = Double.parseDouble(line[4]);
        Location l = new Location(x,y);

        int length = Integer.parseInt(line[5]);
        StationType[] allowedStations = new StationType[length];
        for (int i = 0; i < allowedStations.length; i++) {
            allowedStations[i] = StationType.valueOf(line[i+6]);
        }
        StateKeeper.addStation(new Station(id, name, allowedStations,l));
    }

    private static void addRouteToState(String[] line) {
        int id = Integer.parseInt(line[1]);
        StationType type = StationType.valueOf(line[2]);
        int length = Integer.parseInt(line[3]);
        Station[] stations = new Station[length];
        for (int i = 0; i < stations.length; i++) {
            int stationId = Integer.parseInt(line[4 + i]);
            stations[i] = StateKeeper.getStationById(stationId);
        }
        StateKeeper.addRoute(new Route(id, stations, type));
    }

    private static void addScheduledRideToState(String[] line) {
        int id = Integer.parseInt(line[1]);
        int vehicleId = Integer.parseInt(line[2]);
        int routeId = Integer.parseInt(line[3]);
        int startTime = Integer.parseInt(line[4]);
        StateKeeper.addScheduledRide(
                new ScheduledRide(
                        id,
                        StateKeeper.getVehicleById(vehicleId),
                        StateKeeper.getRouteById(routeId),
                        startTime
                )
        );
    }

    /**
     * This returns the content of a scenario file as a 2D-Array. Look at the scenario files to see how they are built.
     * You do not need to understand the code to use it :)
     * @param scenarioName
     * @return The outer array contains a line of the input file, i.e., one Instance that you will need to create.
     * The inner array (for each instance) depends on what kind of instance should be created. The first element of the
     * array will always be the type of the element, which is one of the following:
     *
     * vehicle, station, route, scheduledRide
     *
     * The following elements of the array are:
     * vehicle:
     *  - The type of vehicle (e.g., SimpleBus)
     *  - Two elements for its current Position (first the X and then the Y Coordinate)
     *
     * station:
     *  - Its ID
     *  - Its Name
     *  - Two elements for its current Position
     *  - The length of the Array containing its allowed Station Types
     *  - The rest of the Array are the Station Types
     *
     * route:
     *  - Its ID
     *  - The common StationType of this Route
     *  - The number of stations on this Route
     *  - The rest of the Array are the Station IDs in this route.
     *
     * scheduledRide:
     *  - Its ID
     *  - The ID of the Vehicle
     *  - The ID of the Route
     *  - The start time
     */
    private static String[][] readScenario(String scenarioName) {
        if (scenarioName.endsWith(".txt")) {
            scenarioName = scenarioName.replace(".txt", "");
        }
        try (Stream<String> lines = Files.lines(Path.of("scenarios", scenarioName + ".txt"), StandardCharsets.UTF_8)) {
            List<String[]> res = lines.map(line -> line.split(",")).toList();
            return res.toArray(new String[0][]);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}

