import java.util.Objects;

/**
 * Represents the (current) Location of something in 2D Space.
 * There is a static method getDistanceBetween() that calucaltes the distance between two points.
 */
public class Location {
    private double x;
    private double y;

    public Location(double x, double y) {
        this.x = x;
        this.y = y;
    }

    public double getY() {
        return y;
    }

    public void setY(double y) {
        this.y = y;
    }

    public double getX() {
        return x;
    }

    public void setX(double x) {
        this.x = x;
    }

    @Override
    public String toString() {
        return "Location{ x=" + x + ", y=" + y + '}';
    }

    /**
     * Manhattan Distance between two Locations
     * @param l1 first location
     * @param l2 second location
     * @return Manhattan Distance (also called Taxicab Distance) between two locations
     */
    public static double getDistanceBetween(Location l1, Location l2) {
        return Math.abs(l1.getX() - l2.getX()) + Math.abs(l1.getY() - l2.getY());
    }

    /**
     * Get the Manhattan Distance (also called Taxicab Distance) to another location
     * @param other the other location
     */
    public double getDistanceTo(Location other) {
        return Location.getDistanceBetween(this, other);
    }

    public void moveTowards(Location other, double speed) {
        double dx = other.getX() - this.x;
        double dy = other.getY() - this.y;

        double absDx = Math.abs(dx);
        double absDy = Math.abs(dy);

        double totalDistance = absDx + absDy;

        // If we're already there or speed is 0, do nothing
        if (totalDistance == 0 || speed <= 0) {
            return;
        }

        // If we can reach the target in this move, just move to it
        if (speed >= totalDistance) {
            this.x = other.getX();
            this.y = other.getY();
            return;
        }

        // Determine how much to move in each direction proportionally
        double moveX = (absDx / totalDistance) * speed;
        double moveY = (absDy / totalDistance) * speed;

        // Apply movement in correct directions
        if (dx > 0) {
            this.x += moveX;
        } else if (dx < 0) {
            this.x -= moveX;
        }

        if (dy > 0) {
            this.y += moveY;
        } else if (dy < 0) {
            this.y -= moveY;
        }
    }

    @Override
    public boolean equals(Object o) {
        if (o == null || getClass() != o.getClass()) return false;
        Location location = (Location) o;
        return Double.compare(x, location.x) == 0 && Double.compare(y, location.y) == 0;
    }

    @Override
    public int hashCode() {
        return Objects.hash(x, y);
    }
}

