package statistics;

import cache.BaseStore;
import cache.BasicCache;
import statistics.distribution.QueryDistribution;

import java.util.List;
import java.util.Random;

public class Experiment {

    private final List<BasicCache<String, String>> caches;
    private final BaseStore<String, String> baseStore;
    private final QueryDistribution queryDistribution;
    private final Random random = new Random();

    public static final int TOTAL_KEYS = 1000;
    public static final int NUM_QUERIES = 100000;

    public Experiment(List<BasicCache<String, String>> caches,
                      BaseStore<String, String> baseStore,
                      QueryDistribution distribution) {
        this.caches = caches;
        this.baseStore = baseStore;
        this.queryDistribution = distribution;
    }

    public void run() {
        System.out.println("=== Starting Cache Experiment ===");
        populateBaseStore();
        runQueries();
        printStats();
    }

    private void populateBaseStore() {
        System.out.println("Populating base store...");
        for (int i = 0; i < TOTAL_KEYS; i++) {
            String key = "key" + i;
            String value = "value" + i;
            baseStore.put(key, value);
        }
        System.out.println("Base store populated with " + TOTAL_KEYS + " items.");
    }

    private void runQueries() {
        System.out.println("Running " + NUM_QUERIES + " queries (" +
                queryDistribution.getClass().getSimpleName() + ")...");

        for (int i = 0; i < NUM_QUERIES; i++) {
            if (i % (NUM_QUERIES/10) == 0) {
                System.out.println("..." + i + "/" + NUM_QUERIES);
            }
            BasicCache<String, String> cache = caches.get(random.nextInt(caches.size()));

            int keyIndex = queryDistribution.nextKeyIndex(TOTAL_KEYS);
            String key = "key" + keyIndex;

            cache.getKey(key);
        }

        System.out.println("Finished running queries.");
    }

    private void printStats() {
        System.out.println("\n=== Experiment Results ===");
        for (int i = 0; i < caches.size(); i++) {
            BasicCache<String, String> cache = caches.get(i);
            printStats(cache);
        }
        System.out.printf("BaseStore stats: %s%n", baseStore.getStats());
        System.out.printf("Requests that did not hit the base store: %.2f %%", (1 - (float) baseStore.getStats().getMisses() / NUM_QUERIES)*100);
    }

    private void printStats(BasicCache<String, String> cache){
        System.out.printf("Cache %s (%s) stats: %s%n", cache.getName(), cache.getClass().getName(), cache.getStats());
        if (cache.getUnderlyingCache() instanceof BasicCache<String, String> basicCache) {
            printStats(basicCache);
        }
    }
}

package statistics.distribution;

import java.util.Random;

/**
 * Generates key indices following a Zipfian (power-law) distribution.
 * A small number of keys will receive most of the accesses.
 */
public class ZipfianDistribution implements QueryDistribution {

    private final Random random = new Random();

    private final int totalKeys;
    private final double exponent; // typically between 0.5 and 2.0 (higher = more skewed)
    private final double[] probabilities;

    public ZipfianDistribution(int totalKeys, double exponent) {
        if (totalKeys <= 0)
            throw new IllegalArgumentException("totalKeys must be positive");
        if (exponent <= 0)
            throw new IllegalArgumentException("exponent must be positive");

        this.totalKeys = totalKeys;
        this.exponent = exponent;

        this.probabilities = computeCumulativeProbabilities();
    }

    /**
     * Precompute normalized cumulative probabilities for all ranks.
     */
    private double[] computeCumulativeProbabilities() {
        double[] cumulative = new double[totalKeys];

        // Compute normalization constant
        double denom = 0.0;
        for (int i = 1; i <= totalKeys; i++) {
            denom += 1.0 / Math.pow(i, exponent);
        }

        // Compute cumulative probabilities
        double sum = 0.0;
        for (int i = 1; i <= totalKeys; i++) {
            sum += (1.0 / Math.pow(i, exponent)) / denom;
            cumulative[i - 1] = sum;
        }

        return cumulative;
    }

    @Override
    public int nextKeyIndex(int totalKeys) {
        // ignore the passed totalKeys since this distribution already knows it
        double sample = random.nextDouble();

        // Binary search through cumulative probabilities
        int low = 0, high = probabilities.length - 1;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (sample <= probabilities[mid]) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}

