public class SendingClient {
    Socket s;
    ObjectOutputStream oos;

    public SendingClient() {
        try {
            s = new Socket("localhost", 60098);
            oos = new ObjectOutputStream(s.getOutputStream());
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    public void send(Message m, boolean printToConsole) {
        try {
            oos.writeObject(m);
            oos.flush();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
        if (printToConsole) {
            Message.printMessage(m, m.sender);
