import java.util.ArrayList;
import java.util.concurrent.atomic.LongAdder;

public class v4Manager {

    public static void main(String[] args) throws Exception {
        ArrayList<Message> queue = new ArrayList<>();

        ArrayList<v4RunnableProducer> producers = new ArrayList<>();
        ArrayList<v4RunnableConsumer> consumers = new ArrayList<>();

        for (int i = 0; i < 100; i++) {
            producers.add(new v4RunnableProducer(queue, "" + i, 100));
            consumers.add(new v4RunnableConsumer(queue));
        }

        System.out.println("Submitting.....");
        for(v4RunnableProducer producer: producers) {
            new Thread(producer).start();
        }
        for(v4RunnableConsumer consumer: consumers) {
            new Thread(consumer).start();
        }
        System.out.println("Waiting.....");
        Thread.sleep(10000);
        System.out.println("Finished Waiting. Stopping.....");
        for(v4RunnableProducer producer: producers) {
            producer.finishProducing();
        }
        for(v4RunnableConsumer consumer: consumers) {
            consumer.finishConsuming();
        }

        System.out.println("Done with FinishConsuming.....");


        System.out.println("Consumed Messages " + v4RunnableConsumer.getConsumedMessages().size());

        if (!queue.isEmpty()) {
            System.out.println("Problem: there are still " + queue.size() + " unprocessed messages");
        }

        for (Message key: v4RunnableConsumer.getConsumedMessages().keySet()) {
            LongAdder v = v4RunnableConsumer.getConsumedMessages().get(key);
            if (v.sum() != 1) {
                System.out.println("Problem: Message was not consumed exactly once. " + key + " was consumed " + v.sum() + " times.");
            }
        }
    }

}

