        this.name = name;
        this.capacity = capacity;
    }

    public void finishProducing() {
        shouldRun = false;
    }

    @Override
    public void run() {
        while (shouldRun) {
            if (queue.size() < capacity) {
                try {
                    queue.add(new Message(counter++, "Hello from Producer " + name  + "!"));
                    Thread.sleep(2);
                } catch (InterruptedException e) {
                    break;
