import java.util.ArrayList;
import java.util.concurrent.BlockingQueue;

public class v6RunnableProducer implements Runnable {

    private final BlockingQueue<Message> queue;
    private final String name;
    private boolean shouldRun = true;
    private final int capacity;
    private int counter = 0;

    public v6RunnableProducer(BlockingQueue<Message> queue, String name, int capacity) {
        this.queue = queue;
        this.name = name;
        this.capacity = capacity;
    }

    public void finishProducing() {
        shouldRun = false;
    }

    @Override
    public void run() {
        while (shouldRun) {
            try {
                queue.take();
            } catch (InterruptedException e) {
                shouldRun = false;
            }
            int currentUsage = queue.size();
                if (currentUsage < capacity) {
                    queue.add(new Message(counter++, "Hello from Producer " + name  + "!"));
                    queue.notify();
                }
        }
    }
