package statistics.distribution;

import java.util.Random;

public class HotKeyDistribution implements QueryDistribution {
    private final Random random = new Random();
    private final double hotKeyFraction; // Fraction of keys that are "hot" (e.g., 0.1 = 10%)

    public HotKeyDistribution(double hotKeyFraction) {
        if (hotKeyFraction <= 0.0 || hotKeyFraction > 1.0) {
            throw new IllegalArgumentException("hotKeyFraction must be in (0, 1]");
        }
        this.hotKeyFraction = hotKeyFraction;
    }

    @Override
    public int nextKeyIndex(int totalKeys) {
        int hotKeyLimit = (int) (totalKeys * hotKeyFraction);

        // 80% chance to choose a hot key, 20% to choose any key
        if (random.nextDouble() < 0.8) {
            return random.nextInt(hotKeyLimit);
        } else {
            return random.nextInt(totalKeys);
        }
    }
}

