}

package solution;

import cache.BasicCache;
import cache.IsCache;

import java.util.Arrays;
import java.util.HashMap;

public class LRUCache<K, T> extends BasicCache<K, T> {

    HashMap<K, T> values = new HashMap<>();
    HashMap<K, Long> lastUsed = new HashMap<>();

    /**
     *
     * @param name the name for later analysis
     * @param capacity        how many items can this cache store?
     * @param underlyingCache where to get the key from if it is not in the cache
     */
    public LRUCache(String name, int capacity, IsCache<K, T> underlyingCache) {
        super(name, capacity, underlyingCache, 5);
    }

    @Override
    public T getKey(K key) {
        if (values.containsKey(key)) {
            getStats().registerHit();
            lastUsed.put(key, System.nanoTime());
            return values.get(key);
        } else {
            getStats().registerMiss();
            T value = getUnderlyingCache().getKey(key);
            if (value == null) {
                throw new IllegalArgumentException("Key is not in underlyingCache: " + key);
            }
            insertValue(key, value);
            return value;
        }
    }

    private void insertValue(K key, T value) {
        if (values.size() > getCapacity()) {
            // We need to delete the least recently used value from the cache.
            K minKey = null;
            long minTime = Long.MAX_VALUE;
            for(K currKey: lastUsed.keySet()) {
                long currTime = lastUsed.get(currKey);
                if (currTime < minTime) {
                    minKey = currKey;
                    minTime = currTime;
                }
            }
            values.remove(minKey);
            lastUsed.remove(minKey);

            if (values.size() > getCapacity()) {
                throw new RuntimeException("LRUCache has more values than it can hold, which should never happen");
            }
        }
        values.put(key, value);
        lastUsed.put(key, System.nanoTime());
    }
}

