        int [] [] quad=new int[n][n];
        int zeile=n/2;
        int spalte=n/2+1;

        for (int i=1;i<=n*n;i++) {
            quad[zeile][spalte]=i;
            zeile=zeile-1;
            spalte=spalte+1;
            if (zeile<0)
