package cache;

import statistics.CacheStats;
import utils.Utils;

public abstract class BasicCache<K, T> implements IsCache<K, T> {
    private final int capacity;
    private final IsCache<K, T> underlyingCache;
    private final long delayMs;
    private final String name;
    CacheStats stats = new CacheStats();

    /**
     *
     * @param capacity how many items can this cache store?
     * @param underlyingCache where to get the key from if it is not in the cache
     */
    public BasicCache(String name, int capacity, IsCache<K,T> underlyingCache, long delayMs) {
        if (capacity <= 0) {
            throw new IllegalArgumentException("Capacity must be positive");
        }
        this.name = name;
        this.capacity = capacity;
        this.underlyingCache = underlyingCache;
        this.delayMs = delayMs;
    }

    /**
     *
     * @param key the key that should be retreived
     * @return the value stored at that key
     */
    @Override
    public T getKey(K key) {
        Utils.sleepMs(delayMs);
        stats.registerMiss();
        return underlyingCache.getKey(key);
    }

    @Override
    public CacheStats getStats() {
        return stats;
    }

    public int getCapacity() {
        return capacity;
    }

    public long getDelayMs() {
        return delayMs;
    }

    public IsCache<K, T> getUnderlyingCache() {
        return underlyingCache;
    }

    @Override
    public String getName() {
        return name;
    }
}

