package client;

import message.Message;
import message.MessageContent;

import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.net.Socket;
import java.nio.ByteBuffer;

public class ReceivingClient implements Runnable {
    Socket s;
    int room;
    boolean printOwnMessages;

    public ReceivingClient(int room, boolean printOwnMessages) {
        try {
            s = new Socket("localhost", 60097);
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
        this.room = room;
        this.printOwnMessages = printOwnMessages;
    }


    @Override
    public void run() {
        try(
                DataOutputStream dos = new DataOutputStream(s.getOutputStream());
                DataInputStream dis = new DataInputStream(s.getInputStream())
        ) {
            // Write the room we want to receive at
            // We will only get Messages for that Room from here
            // Send the room ID as an int (4 bytes)
            dos.writeInt(room);
            dos.flush();

            while (true) {
                // Read the incoming message (3 integers)
                int prio = dis.readInt();
                int sender = dis.readInt();
                int contentIndex = dis.readInt();

                if (sender == Config.USER_ID && !printOwnMessages) {
                    continue; // skip self messages
                }

                Message m = new Message(prio, sender, room, MessageContent.values()[contentIndex]);
                Message.printMessage(m, sender);
            }
        } catch (IOException e) {
            System.err.println("Connection closed or error: " + e.getMessage());
        }

    }
}

