package solution;

import cache.BasicCache;
import cache.IsCache;

import java.util.HashMap;
import java.util.Map;

public class LFUCache<K, T> extends BasicCache<K, T> {

    private final HashMap<K, T> values = new HashMap<>();
    private final HashMap<K, Integer> accessCounts = new HashMap<>();

    /**
     * @param name            the name for later analysis
     * @param capacity        how many items this cache can hold
     * @param underlyingCache where to fetch items that aren't in this cache
     */
    public LFUCache(String name, int capacity, IsCache<K, T> underlyingCache) {
        super(name, capacity, underlyingCache, 5);
    }

    @Override
    public T getKey(K key) {
        if (values.containsKey(key)) {
            getStats().registerHit();
            accessCounts.put(key, accessCounts.getOrDefault(key, 0) + 1);
            return values.get(key);
        } else {
            getStats().registerMiss();
            T value = getUnderlyingCache().getKey(key);
            if (value == null) {
                throw new IllegalArgumentException("Key not found in underlying cache: " + key);
            }
            insertValue(key, value);
            return value;
        }
    }

    private void insertValue(K key, T value) {
        if (values.size() >= getCapacity()) {
            // Evict least frequently used key
            K leastUsedKey = null;
            int minCount = Integer.MAX_VALUE;

            for (Map.Entry<K, Integer> entry : accessCounts.entrySet()) {
                if (entry.getValue() < minCount) {
                    minCount = entry.getValue();
                    leastUsedKey = entry.getKey();
                }
            }

            if (leastUsedKey != null) {
                values.remove(leastUsedKey);
                accessCounts.remove(leastUsedKey);
            }
        }

        values.put(key, value);
        accessCounts.put(key, 1); // first access
    }
}

package message;

import java.io.Serial;
import java.io.Serializable;

public class Message implements Serializable {

    @Serial
    private static final long serialVersionUID = 42L;

    public int priority;
    public int sender;
    public int receiver;
    public MessageContent content;

    public Message(int priority, int sender, int receiver, MessageContent content) {
        this.priority = priority;
        this.sender = sender;
        this.receiver = receiver;
        this.content = content;
    }

    // ANSI color codes for terminal text
    public static final String RESET = "\u001B[0m";
    public static final String RED = "\u001B[31m";
    public static final String GREEN = "\u001B[32m";
    public static final String YELLOW = "\u001B[33m";
    public static final String BLUE = "\u001B[34m";
    public static final String CYAN = "\u001B[36m";

    // Default print method (no color)
    public static void printMessage(Message m) {
        printMessage(m, null);
    }

    // Specify color as int (so that you can just pass the sender as color)
    public static void printMessage(Message m, int colorIndex) {
        String color = "";
        switch (colorIndex % 5) {
            case 0:
                color = "red";
                break;
            case 1:
                color = "green";
                break;
            case 2:
                color = "yellow";
                break;
            case 3:
                color = "blue";
                break;
            case 4:
                color = "cyan";
                break;
        }
        printMessage(m, color);
    }

    // Specify color as string. Note that we only implemented some colors.
    public static void printMessage(Message m, String color) {
        String colorCode = "";

        if (color != null) {
            switch (color.toLowerCase()) {
                case "red":
                    colorCode = RED;
                    break;
                case "green":
                    colorCode = GREEN;
                    break;
                case "yellow":
                    colorCode = YELLOW;
                    break;
                case "blue":
                    colorCode = BLUE;
                    break;
                case "cyan":
                    colorCode = CYAN;
                    break;
                default:
                    colorCode = RESET; // fallback if unknown color
            }
        }

        System.out.println(colorCode +
                "Priority: " + m.priority + "\t" +
                "Sender: " + m.sender + "\t" +
                "Receiver: " + m.receiver + "\t" +
                "Content: " + (m.content != null ? m.content.toString() : "(no content)") +
                RESET);
    }
}

