package secretClient;

import client.Config;
import message.Message;
import message.MessageContent;

import java.io.DataInputStream;
import java.io.DataOutputStream;
import java.io.IOException;
import java.net.Socket;
import java.nio.charset.Charset;
import java.util.ArrayList;

public class SecretReceiver implements Runnable {
    int room = 0x42424242;

    Socket s = new Socket("localhost", 60097);

    public SecretReceiver() throws IOException {
    }

    @Override
    public void run() {
        try(
                DataOutputStream dos = new DataOutputStream(s.getOutputStream());
                DataInputStream dis = new DataInputStream(s.getInputStream())
        ) {
            // Write the room we want to receive at
            // We will only get Messages for that Room from here
            // Send the room ID as an int (4 bytes)
            dos.writeInt(room);
            dos.flush();

            ArrayList<Byte> messageBytes = new ArrayList<>();

            while (true) {
                // Read the incoming message (3 integers)
                int prio = dis.readInt();
                int sender = dis.readInt();
                int contentIndex = dis.readInt();

                if (contentIndex == MessageContent.WAVE.ordinal()) {
                    messageBytes.add((byte) prio);
                }

                if (contentIndex == MessageContent.GOODBYE.ordinal()) {
                    byte[] msgRaw = new byte[messageBytes.size()];
                    for (int i = 0; i < msgRaw.length; i++) {
                        msgRaw[i] = messageBytes.get(i);
                    }
                    String s = new String(msgRaw, Charset.defaultCharset());
                    messageBytes.clear();

                    System.out.println("Decoded Secret Message: " + s);
                }

                Message m = new Message(prio, sender, room, MessageContent.values()[contentIndex]);
                Message.printMessage(m, sender);
            }
        } catch (IOException e) {
            System.err.println("Connection closed or error: " + e.getMessage());
        }
    }
}

