  }
  public void ziehe (char richtung, int anzahl) {
    if (richtung == '-')
      ziehe(anzahl, 0);
    else if (richtung == '|')
      ziehe(0, anzahl);
    else if (richtung == '/')
      ziehe(anzahl,anzahl);
    else if (richtung == '\\')
      ziehe(anzahl,-anzahl);
