public class Queue {

        private QueueNode head;

        public Queue() {
            this.head = null;
        }

        public void enqueue(TreeNode value) {
            QueueNode newQueueNode = new QueueNode();
            newQueueNode.value = value;

            if (head == null) {
                head = newQueueNode;
                return;
            }

            QueueNode current = head;
            while (current.next != null) {
                current = current.next;
            }

            current.next = newQueueNode;
        }


        public TreeNode dequeue() {
            if (head == null) {
                System.err.println("Queue ist leer");
                return null;
            }

            TreeNode value = head.value;
            head = head.next;
            return value;
        }

        public TreeNode peek() {
            if (head == null) {
                System.out.println("Queue ist leer");
                return null;// eigentlich IllegalStateException, aber ist noch nicht bekannt
            }
            return head.value;
        }

        public boolean isEmpty() {
            return head == null;
        }

        @Override
        public String toString() {
            StringBuilder sb = new StringBuilder("Queue: ");
            QueueNode current = head;

            while (current != null) {
                sb.append(current.value).append(" ");
                current = current.next;
            }

            return sb.toString();
        }

