package Aufgabe26;

import Aufgabe24.Stack;

public class Check {

    /**
     * In dieser Aufgabe sollen Sie mit Ihrer Stack-Klasse prüfen, ob ein String korrekt geschachtelte Klammern enthält.
     * Die Strings können runde, eckige und geschweifte Klammern enthalten, die nur Klammern aus derselben Art
     * schließen. Schreiben Sie dafür eine passende Methode, die einen String bekommt und einen boolean zurückgibt.
     * Hier sehen Sie einige Beispielaufrufe und den dazu passenden Rückgabewert.
     * "()" -> true
     * "([])" -> true
     * "([]]" -> false
     * "(([]))" -> true
     * "{[(])}" -> false
     * ")(" -> false
     * @param s ist der zu prüfende String
     * @return
     */
    public static boolean checkBrackets(String s) {
        Stack stack = new Stack();

        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);

            if (c == '(' || c == '[' || c == '{') {
                stack.push(c);
            }

            else if (c == ')' || c == ']' || c == '}') {
                if (stack.isEmpty()) {
                return false;
                }


                char top = stack.pop();

                if ((c == ')' && top != '(') ||
                        (c == ']' && top != '[') ||
                        (c == '}' && top != '{')) {
                    return false;
                }
            }
        }
        return stack.isEmpty();
    }

    public static void main(String[] args) {
        System.out.println(checkBrackets("()"));
        System.out.println(checkBrackets("()]"));
        System.out.println(checkBrackets("(hdj)"));
        System.out.println(checkBrackets("{([])}"));
    }

}

package Aufgabe19_20;

/**
 * Implementieren Sie eine einfach verkettete Liste, die Integer-Werte speichert. Als Basis für Ihre Liste können Sie
 * die folgende Klasse verwenden. Erstellen Sie außerdem eine Klasse List, die eine Referenz auf den Kopf der Liste
 * besitzt.
 */
public class LinkedList{

    public ListElement head;

    public LinkedList() {
        this.head = null;
    }

    /**
     * (a) Schreiben Sie eine Methode insert, mit der Werte zur Liste hinzugefügt werden können. Diese soll einen
     * Wert und einen Index als Input bekommen. Wenn der Index größer als die Länge der Liste ist, können Sie das
     * Element einfach am Ende der Liste anhängen.
     * @param value der eingefügt werden soll
     * @param index an dem der value eingefügt werden soll
     */
    public void insert(int value, int index){
        ListElement newElement = new ListElement(value);

        if (head == null || index <= 1) {
            newElement.next = head;
            head = newElement;
            return;
        }

        ListElement current = head;
        int pos = 0;

        while (current.next != null && pos < index - 1) {
            current = current.next;
            pos++;
        }

        newElement.next = current.next;
        current.next = newElement;
    }

    /**
     * (b) Überschreiben Sie nun die toString-Methode. Wie unterscheiden sich die rekursive und iterative Variante
     * voneinander?
     */
    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("[ ");
        ListElement current = head;

        while (current != null) {
            sb.append(current.value).append(" ");
            current = current.next;
        }

        sb.append("]");
        return sb.toString();
    }

    /**
     * rekursiver Ansatz:
     */
    public String toStringRecursive() {
        return "[ " + toStringRecursiveHelper(head) + "]";
    }

    private String toStringRecursiveHelper(ListElement elem) {
        if (elem == null) {
            return "";
        }
        return elem.value + " " + toStringRecursiveHelper(elem.next);
    }

    /**
     * (c) Schreiben Sie eine remove-Methode. Diese soll den Index eines zu entfernenden Elements bekommen und es
     * aus der Liste entfernen. Achten Sie darauf, die Liste wieder korrekt zusammenzuhängen, wenn Sie einen Wert aus
     * der Mitte entfernen.
     * @param index an dem Wert entfernt werden soll
     * @return entfernten Wert
     */
    public Number remove(int index) {
        if (head == null) {
            System.err.println("Liste ist leer");
            return null;
        }

        if (index <= 1) {
            Number value = head.value;
            head = head.next;
            return value;
        }

        ListElement current = head;
        int pos = 0;

        while (current.next != null && pos < index - 1) {
            current = current.next;
            pos++;
        }

        if (current.next == null) {
            System.err.println("Index zu groß");
            return null;
        }

        Number removedValue = current.next.value;
        current.next = current.next.next;

        return removedValue;
    }

    /**
     * Aufgabe 20: Einfach verkettete Listen: umdrehen
     * Schreiben Sie eine Methode reverse, die die gesamte Reihenfolge der Liste umdreht. Iterieren Sie dafür einmal
     * über die Liste und ändern Sie die Verbindungen zwischen den Listenelementen entsprechend. Achten Sie auch
     * darauf, die Variable head der Liste zu aktualisieren.
     */
    public void reverse(){
        ListElement previous = null;
        ListElement current = head;
        ListElement next = null;

        while (current != null) {
            next = current.next;
            current.next = previous;
            previous = current;
            current = next;
        }

        head = previous;

    }


    public static void main(String[] args) {
        LinkedList list = new LinkedList();

        System.out.println("Leere Liste:");
        System.out.println(list);

        list.insert(10, 1);
        list.insert(20, 2);
        list.insert(15, 1);
        list.insert(30, 100);

        System.out.println("\nListe nach insert:");
        System.out.println(list);

        System.out.println("\nEntferne Element an Index 0:");
        System.out.println("Entfernt: " + list.remove(0));
        System.out.println(list);

        System.out.println("\nEntferne Element in der Mitte (Index 1):");
        System.out.println("Entfernt: " + list.remove(1));
        System.out.println(list);

        System.out.println("\nEntferne Element mit zu großem Index:");
        System.out.println("Entfernt: " + list.remove(10));
        System.out.println(list);

        list.reverse();
        System.out.println("\nListe nach Reverse: ");
        System.out.println(list);

    }

    /*
    (d)Überlegen Sie wie Sie Ihre Klasse anpassen müssten, damit sie als Stack bzw. Queue funktioniert.

    Um die Liste als Stack zu verwenden, werden Elemente ausschließlich am Kopf der Liste eingefügt und entfernt (push und pop).
    Dadurch würden dann alle Operationen dem LIFO-Prinzip folgen.

    Für eine Queue wird zusätzlich zur Kopf-Referenz eine Referenz auf das letzte Element (tail) benötigt.
    Neue Elemente werden am Ende eingefügt (enqueue) und am Kopf entfernt (dequeue).
    Dadurch würden dann ale operationen dem FIFO-Prinzip folgen.
     */
}

package Aufgabe9;

import java.util.Arrays;

/**
 * (!) Aufgabe 9: Bubble, insertion und selection sort: Implementierung
 * Implementieren Sie nun die drei Ihnen bekannten Sortieralgorithmen für Integer-Arrays.
 * Achten Sie zunächst darauf, dass Sie keine Kopie des ursprünglichen Arrays erstellen,
 * sondern es direkt in place sortieren. Probieren Sie Ihre Implementierungen für verschiedene Inputwerte aus.
 * Diskutieren Sie, wie sich die Implementierungen unterscheiden, wenn Sie Arrays in place sortieren oder
 * stattdessen Kopien erstellen. Ist das eine gute Idee?
 */
public class SortingAlgorithms {

    public static void insertionSort(int[] array) {

        for (int i = 1; i < array.length; i++) {
            int key = array[i];
            int j = i - 1;

            while (j >= 0 && array[j] > key) {
                array[j + 1] = array[j];
                j--;
            }
            array[j + 1] = key;

        }
    }
        public static void bubbleSort(int[] arr){

            int temp;
            for(int j = arr.length; j > 0 ; j--) {
                for (int i = 0; i < j - 1; i++) {
                    if (arr[i] > arr[i + 1]) {
                        temp = arr[i];
                        arr[i] = arr[i + 1];
                        arr[i + 1] = temp;
                    }
                }
            }
        }

    public static void selectionSort(int[] array) {

        for (int i = 0; i < array.length - 1; i++) {
            int minValue = array[i];
            int minIndex = i;

            for (int j = i + 1; j < array.length; j++) {
                if (array[j] < minValue) {
                    minValue = array[j];
                    minIndex = j;
                }
            }

            array[minIndex] = array[i];
            array[i] = minValue;

        }

    }

    /*
    INFO: Beim in-place Sortieren wird das Original-Array direkt verändert,
     beim Sortieren über Kopien bleibt das Original unverändert, braucht aber zusätzlichen Speicher.
     Kopien sind eine gute Idee, wenn du das Original noch brauchst (z. B. für Vergleiche/Debugging),
     in-place ist besser bei Speicherknappheit und wenn die Mutation okay ist.
     */
    public static void main(String[] args) {

        int[] arr = {-10, 23, 27, 5, 7, 30, 17, 0, -3};
        System.out.println("Original array:   " + Arrays.toString(arr));
        insertionSort(arr);
        int[] arr2 = {-10, 23, 27, 5, 7, 30, 17, 0, -3};
        System.out.println("Insertion Sort:   " + Arrays.toString(arr));
        bubbleSort(arr2);
        System.out.println("Bubble Sort:      " + Arrays.toString(arr2));
        int[] arr3 = {-10, 23, 27, 5, 7, 30, 17, 0, -3};
        selectionSort(arr3);
        System.out.println("Selection Sort:   " + Arrays.toString(arr3));
    }
}

