     * Werte weiter nach vorne geschoben werden. Denken Sie auch daran, den internen, nächsten Index um eine Stelle
     * zurückzusetzen.
     * @param index des zu löschenden Elements
     * @return gelöschter Wert
     */
    public Number remove(int index) {
        if (index < 0 || index >= size) {
            System.err.println("Ungültiger Index: " + index);
        }
        Number removedValue = data[index];
        for (int i = index; i < size - 1; i++) {
            data[i] = data[i + 1];
        }
        data[size - 1] = null;
        size--;
        return removedValue;
    }

    /**
