 * Listen?
 */
public class Queue {

    private Node head;

    public Queue() {
        this.head = null;
    }

    public void enqueue(char value) {
        Node newNode = new Node();
        newNode.value = value;

        if (head == null) {
            head = newNode;
            return;
        }

        Node current = head;
        while (current.next != null) {
            current = current.next;
        }

        current.next = newNode;
    }


    public char dequeue() {
        if (head == null) {
            System.err.println("Queue ist leer");
            return 0;// eigentlich IllegalStateException, aber ist noch nicht bekannt
        }

        char value = head.value;
        head = head.next;
        return value;
    }

    public char peek() {
        if (head == null) {
            System.out.println("Queue ist leer");
            return 0;// eigentlich IllegalStateException, aber ist noch nicht bekannt
        }
        return head.value;
    }

    public boolean isEmpty() {
        return head == null;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder("Queue: ");
        Node current = head;

        while (current != null) {
            sb.append(current.value).append(" ");
            current = current.next;
        }

        return sb.toString();
    }

    public static void main(String[] args) {
