        System.out.println("Peek: " + queue.peek());
        System.out.println(queue);
        System.out.println("Dequeue: " + queue.dequeue());
        System.out.println(queue);
    }

    /*
    Es ist effizienter, zusätzlich eine Referenz auf das Ende der Queue zu speichern,
    da neue Elemente dann direkt am Ende eingefügt werden können und kein Durchlaufen der Liste nötig ist.
    Dieser Vorteil ist besonders bei einfach verketteten Listen relevant, während doppelt verkettete Listen
    zwar ebenfalls einen schnellen Zugriff auf das Ende erlauben, dafür aber mehr Speicher benötigen.
     */

