public class Complexity {

    // (1) -> maximal O(n^2)
    static void someMethod(int[][] arr) {
        for (int i = 0; i < arr.length; i++) {
            for (int j = 0; j < arr[i].length; j++) {
                int x = (i * j) % 7;
            }
        }
    }
