        while (n > 1) {
            n = n / 2;
            double y = Math.sqrt(n);
        }
    }
    // (4) -> maximal O(2^n)
    static int recursionAdventure(int x) {
        if (x <= 1) return 1;
        int a = recursionAdventure(x - 1);
        int b = recursionAdventure(x - 2);
        return a+b;
    }

